UPDATE authrt_info SET AUTHRT_NM = #{authrtNm}, AUTHRT_EXPLN = #{authrtExpln},
       AUTHRT_STTS_NM = #{authrtSttsNm}, USE_YN = #{useYn}, MDFCN_DT = NOW(), MDFR_SN = #{mdfrSn}
 WHERE AUTHRT_SN = #{authrtSn} AND USE_YN = 'Y'
